  /* 基础大小 */
  flex-basis: auto; /* auto | 具体数值 */

  /* 简写形式 */
  flex: 0 1 auto; /* flex-grow + flex-shrink + flex-basis */

  /* 单独对齐 */
  align-self: auto; /* auto | flex-start | flex-end | center | baseline | stretch */

