  private async analyzeCode(code: string, type: string): Promise<any> {
    switch (type) {
      case 'complexity':
        return this.analyzeComplexity(code);
      case 'security':
        return this.analyzeSecurity(code);
      case 'performance':
        return this.analyzePerformance(code);
      case 'style':
        return this.analyzeStyle(code);
      default:
