// - setTimeout
// - setInterval
// - setImmediate (Node.js)
// - I/O操作
// - UI渲染

// 微任务（Microtask）
// - Promise.then/catch/finally
// - async/await
// - process.nextTick (Node.js)
// - MutationObserver

// 执行优先级：同步代码 > 微任务 > 宏任务

console.log('1');

setTimeout(() => {
    console.log('2');
    Promise.resolve().then(() => console.log('3'));
}, 0);

new Promise(resolve => {
    console.log('4');
    resolve();
}).then(() => {
    console.log('5');
    setTimeout(() => console.log('6'), 0);
});

console.log('7');

// 输出：1, 4, 7, 5, 2, 3, 6
