### 1.4 实际应用案例

```javascript
// 实际开发中的异步处理
class DataLoader {
    constructor() {
        this.cache = new Map();
    }

    async loadData(url) {
        // 检查缓存
        if (this.cache.has(url)) {
            console.log('从缓存加载数据');
            return this.cache.get(url);
        }

        console.log('开始加载数据');

        try {
            // 模拟网络请求
            const data = await this.fetchData(url);

            // 缓存数据
            this.cache.set(url, data);

            console.log('数据加载完成');
            return data;
        } catch (error) {
            console.error('数据加载失败:', error);
            throw error;
        }
    }

    fetchData(url) {
        return new Promise((resolve) => {
            setTimeout(() => {
                resolve({ url, data: `数据来自${url}`, timestamp: Date.now() });
            }, 1000);
        });
    }
}

// 使用示例
const loader = new DataLoader();

loader.loadData('https://api.example.com/data1')
    .then(data => console.log('数据1:', data))
    .catch(error => console.error(error));

loader.loadData('https://api.example.com/data2')
    .then(data => console.log('数据2:', data))
    .catch(error => console.error(error));

// 第二次加载相同URL（从缓存）
setTimeout(() => {
    loader.loadData('https://api.example.com/data1')
        .then(data => console.log('数据1（缓存）:', data));
}, 2000);
```

