        title: '页面未找到'
      }
    }
  ],
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    } else {
      return { x: 0, y: 0 }
    }
  }
})

export default router
```

## 3. Vue过滤器与工具函数

### 3.1 全局过滤器

虽然Vue 3中移除了过滤器，但在Vue 2中过滤器仍然很有用：

```javascript
// filters/index.js
import Vue from 'vue'

// 日期格式化
Vue.filter('formatDate', (value, format = 'YYYY-MM-DD') => {
  if (!value) return ''
  return dayjs(value).format(format)
})

// 数字千分位
Vue.filter('formatNumber', (value) => {
  if (!value) return '0'
  return value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',')
})

// 文件大小格式化
Vue.filter('formatFileSize', (value) => {
  if (!value) return '0 B'

  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  let size = value
  let unitIndex = 0

  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024
    unitIndex++
  }

  return `${size.toFixed(2)} ${units[unitIndex]}`
})

// 随机数生成（用于测试数据）
Vue.filter('random30', (number) => {
  const num = parseInt(number)
  if (num < 30) {
    return Math.round(Math.random() * 20 + 30)
  }
  return num
})
```

### 3.2 局部过滤器

```vue
<template>
  <div>
    <p>创建时间：{{ createTime | formatDate('YYYY-MM-DD HH:mm:ss') }}</p>
    <p>文件大小：{{ fileSize | formatFileSize }}</p>
    <p>在线人数：{{ onlineCount | random30 }}人</p>
  </div>
</template>

<script>
export default {
  filters: {
    // 局部过滤器
    currency(value, symbol = '¥') {
      if (!value) return `${symbol}0.00`
      return `${symbol}${parseFloat(value).toFixed(2)}`
    },

    statusText(value) {
      const statusMap = {
        0: '待处理',
        1: '处理中',
        2: '已完成',
        3: '已取消'
      }
      return statusMap[value] || '未知状态'
    }
  }
}
</script>
```

## 4. Vue性能优化技巧

### 4.1 组件懒加载

```javascript
// 路由懒加载
const routes = [
  {
    path: '/dashboard',
    component: () => import('@/views/Dashboard.vue')
  }
]

// 异步组件
Vue.component('async-component', () => import('./AsyncComponent.vue'))

// 高级异步组件
const AsyncComponent = () => ({
  component: import('./AsyncComponent.vue'),
  loading: LoadingComponent,
  error: ErrorComponent,
  delay: 200,
  timeout: 3000
})
```

### 4.2 使用Object.freeze优化大数据

```javascript
// 对于大型静态数据，使用Object.freeze避免响应式转换
export default {
  data() {
    return {
      // 大型列表数据不会被响应式处理，提升性能
      largeList: Object.freeze(getLargeListData()),
      // 静态配置数据
      config: Object.freeze({
        apiBaseUrl: 'https://api.example.com',
        timeout: 5000
      })
    }
  }
}
```

### 4.3 v-if vs v-show的选择

```vue
<template>
  <div>
    <!-- 条件很少改变时使用v-if -->
    <heavy-component v-if="showComponent" />

    <!-- 频繁切换时使用v-show -->
    <popup-component v-show="showPopup" />
  </div>
</template>
```

### 4.4 key的正确使用

```vue
<template>
  <!-- 错误示例：使用index作为key -->
  <div v-for="(item, index) in list" :key="index">
    {{ item.name }}
  </div>

  <!-- 正确示例：使用唯一ID作为key -->
  <div v-for="item in list" :key="item.id">
    {{ item.name }}
  </div>

  <!-- 当列表项包含子组件且需要重新渲染时 -->
  <user-card
    v-for="user in userList"
    :key="`user-${user.id}-${user.updatedAt}`"
    :user="user"
  />
</template>
```

## 5. 实战案例总结

### 5.1 项目结构建议

