// Inferred string interning pattern - 推断的字符串驻留模式
class StringIntern {
  private static pool = new Map<string, string>();  // 字符串池

  static intern(str: string): string {
    if (!this.pool.has(str)) {
      this.pool.set(str, str);
    }
    return this.pool.get(str)!;
  }
}

