		} else {
			that.$bus.$emit("hudong", false);
		}
	};

	// 关键代码
	let debounce = function (fn, time) {
		let timeout = null; // 创建一个标记用来存放定时器的返回值
		return function () {
			clearTimeout(timeout); // 每当用户输入的时候把前一个 setTimeout clear 掉
			timeout = setTimeout(() => {
