// 开头添加
array_unshift($array, "0");

// 指定位置插入
array_splice($array, 2, 0, ["x", "y"]);
```

### 删除元素

```php
$array = ["a", "b", "c", "d", "e"];

// 删除末尾元素
$last = array_pop($array);  // 返回 "e"

// 删除开头元素
$first = array_shift($array);  // 返回 "a"

// 删除指定键
unset($array[2]);

// 删除连续范围
