```php
class ConfigManager {
    private $config = [];
    private $defaults = [
        'database' => [
            'host' => 'localhost',
            'port' => 3306,
            'charset' => 'utf8'
        ],
        'cache' => [
            'driver' => 'file',
            'ttl' => 3600
        ]
    ];

    public function __construct(array $config = []) {
        $this->config = array_merge_recursive($this->defaults, $config);
    }

    // 获取配置值（支持点号分隔的嵌套键）
    public function get($key, $default = null) {
        $keys = explode('.', $key);
        $value = $this->config;

        foreach ($keys as $k) {
            if (!isset($value[$k])) {
                return $default;
            }
            $value = $value[$k];
        }

        return $value;
    }

    // 设置配置值
    public function set($key, $value) {
        $keys = explode('.', $key);
        $current = &$this->config;

        foreach ($keys as $k) {
            if (!isset($current[$k]) || !is_array($current[$k])) {
                $current[$k] = [];
            }
            $current = &$current[$k];
        }

        $current = $value;
    }

    // 检查配置是否存在
    public function has($key) {
        return $this->get($key) !== null;
    }

    // 获取所有配置
    public function all() {
        return $this->config;
    }

    // 从文件加载配置
    public function loadFromFile($file) {
        if (file_exists($file)) {
            $content = include $file;
            if (is_array($content)) {
                $this->config = array_merge_recursive($this->config, $content);
            }
        }
    }
}

// 使用示例
