### 3.2 数据优化策略

#### 数据缓存机制

```javascript
// utils/cache.js
class CacheManager {
  constructor() {
    this.cache = new Map()
    this.maxSize = 50
    this.defaultExpireTime = 5 * 60 * 1000 // 5分钟
  }

  // 设置缓存
  set(key, data, expireTime = this.defaultExpireTime) {
    // 检查缓存大小
    if (this.cache.size >= this.maxSize) {
      // 删除最旧的缓存
      const firstKey = this.cache.keys().next().value
      this.cache.delete(firstKey)
    }

    this.cache.set(key, {
      data,
      timestamp: Date.now(),
      expireTime
    })
  }

  // 获取缓存
  get(key) {
    const item = this.cache.get(key)

    if (!item) {
      return null
    }

    // 检查是否过期
    if (Date.now() - item.timestamp > item.expireTime) {
      this.cache.delete(key)
      return null
    }

    return item.data
  }

  // 删除缓存
  delete(key) {
    this.cache.delete(key)
  }

  // 清空缓存
  clear() {
    this.cache.clear()
  }

  // 获取缓存大小
  size() {
    return this.cache.size
  }
}

const cacheManager = new CacheManager()
module.exports = cacheManager
```

```javascript
// 使用缓存优化API请求
const cacheManager = require('./cache')

class ApiService {
  // 带缓存的请求方法
  static async getCachedData(url, params = {}, cacheExpire = 60000) {
    const cacheKey = `${url}?${JSON.stringify(params)}`

    // 尝试从缓存获取
    const cachedData = cacheManager.get(cacheKey)
    if (cachedData) {
      console.log('从缓存获取数据:', url)
      return cachedData
    }

    // 缓存未命中，发起网络请求
    try {
      const response = await this.request(url, params)

      // 存入缓存
      cacheManager.set(cacheKey, response, cacheExpire)

      return response
    } catch (error) {
      console.error('请求失败:', error)
      throw error
    }
  }

  static async request(url, params) {
    return new Promise((resolve, reject) => {
      wx.request({
        url: `https://api.example.com${url}`,
        method: 'GET',
        data: params,
        success: (res) => {
          if (res.statusCode === 200) {
            resolve(res.data)
          } else {
            reject(new Error(`HTTP ${res.statusCode}`))
          }
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }
}
```

### 3.3 图片优化

```javascript
// utils/imageOptimizer.js
class ImageOptimizer {
  // 图片懒加载
  static lazyLoad() {
    const observer = wx.createIntersectionObserver()

    observer.relativeToViewport({
      bottom: 100 // 提前100px开始加载
    }).observe('.lazy-image', (res) => {
      if (res.intersectionRatio > 0) {
        const img = res.target
        const src = img.dataset.src

        if (src && !img.dataset.loaded) {
          img.dataset.loaded = 'true'

          wx.getImageInfo({
            src: src,
            success: (imageRes) => {
              img.src = imageRes.path
              img.classList.add('loaded')
            },
            fail: () => {
              img.src = '/images/placeholder.png'
              img.classList.add('error')
            }
          })
        }
      }
    })
  }

  // 图片压缩
  static compressImage(src, quality = 0.8) {
    return new Promise((resolve, reject) => {
      wx.compressImage({
        src: src,
        quality: quality * 100,
        success: (res) => {
          resolve(res.tempFilePath)
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }

  // 批量处理图片
  static async processImages(imageList) {
    const results = []

    for (const image of imageList) {
      try {
        const compressedImage = await this.compressImage(image.src, image.quality || 0.8)
        results.push({
          ...image,
          compressedSrc: compressedImage
        })
      } catch (error) {
        console.error('图片处理失败:', image.src, error)
        results.push({
          ...image,
          compressedSrc: image.src
        })
      }
    }

    return results
  }
}

module.exports = ImageOptimizer
```

## 4. 小程序与ECharts集成

### 4.1 集成ECharts到小程序

#### 下载和配置

1. 从ECharts官网下载适用于小程序的版本
2. 将 `ec-canvas` 文件夹复制到项目 `components` 目录下

#### 基础配置

```javascript
// components/ec-canvas/ec-canvas.js
import * as echarts from './echarts.min.js'

Component({
  properties: {
    canvasId: {
      type: String,
      value: 'ec-canvas'
    },
    ec: {
      type: Object
    }
  },

  data: {
    isReady: false
  },

  ready() {
    if (!this.data.ec) {
      console.warn('组件需绑定 ec 变量')
      return
    }

    this.init()
  },

  methods: {
    init() {
      const canvasNode = this.selectComponent(`#${this.data.canvasId}`)

      if (!canvasNode) {
        console.warn('Canvas节点不存在')
        return
      }

      const query = this.createSelectorQuery()
      query.select(`#${this.data.canvasId}`)
        .fields({ node: true, size: true })
        .exec((res) => {
          const canvas = res[0].node
          const ctx = canvas.getContext('2d')

          const dpr = wx.getSystemInfoSync().pixelRatio
          canvas.width = res[0].width * dpr
          canvas.height = res[0].height * dpr

          const chart = echarts.init(canvas, null, {
            width: res[0].width,
            height: res[0].height,
            devicePixelRatio: dpr
          })

          canvas.setChart(chart)

          if (this.data.ec && typeof this.data.ec.onInit === 'function') {
            this.data.ec.onInit(canvas, res[0].width, res[0].height, dpr)
          }

          this.chart = chart
          this.setData({ isReady: true })
        })
    },

    // 更新图表配置
    setOption(option, notMerge = false, lazyUpdate = false) {
      if (this.chart) {
        this.chart.setOption(option, notMerge, lazyUpdate)
      }
    },

    // 获取图表实例
    getChart() {
      return this.chart
    }
  }
})
```

