### 3.2 数据优化策略

#### 数据缓存机制

```javascript
// utils/cache.js
class CacheManager {
  constructor() {
    this.cache = new Map()
    this.maxSize = 50
    this.defaultExpireTime = 5 * 60 * 1000 // 5分钟
  }

  // 设置缓存
  set(key, data, expireTime = this.defaultExpireTime) {
    // 检查缓存大小
    if (this.cache.size >= this.maxSize) {
      // 删除最旧的缓存
      const firstKey = this.cache.keys().next().value
      this.cache.delete(firstKey)
    }

    this.cache.set(key, {
      data,
      timestamp: Date.now(),
      expireTime
    })
  }

  // 获取缓存
  get(key) {
    const item = this.cache.get(key)

    if (!item) {
      return null
    }

    // 检查是否过期
    if (Date.now() - item.timestamp > item.expireTime) {
      this.cache.delete(key)
      return null
    }

    return item.data
  }

  // 删除缓存
  delete(key) {
    this.cache.delete(key)
  }

  // 清空缓存
  clear() {
    this.cache.clear()
  }

  // 获取缓存大小
  size() {
    return this.cache.size
  }
}

const cacheManager = new CacheManager()
module.exports = cacheManager
```

```javascript
// 使用缓存优化API请求
const cacheManager = require('./cache')

class ApiService {
  // 带缓存的请求方法
  static async getCachedData(url, params = {}, cacheExpire = 60000) {
    const cacheKey = `${url}?${JSON.stringify(params)}`

    // 尝试从缓存获取
    const cachedData = cacheManager.get(cacheKey)
    if (cachedData) {
      console.log('从缓存获取数据:', url)
      return cachedData
    }

    // 缓存未命中，发起网络请求
    try {
      const response = await this.request(url, params)

      // 存入缓存
      cacheManager.set(cacheKey, response, cacheExpire)

      return response
    } catch (error) {
      console.error('请求失败:', error)
      throw error
    }
  }

  static async request(url, params) {
    return new Promise((resolve, reject) => {
      wx.request({
        url: `https://api.example.com${url}`,
        method: 'GET',
        data: params,
        success: (res) => {
          if (res.statusCode === 200) {
            resolve(res.data)
          } else {
            reject(new Error(`HTTP ${res.statusCode}`))
          }
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }
}
