### 3.3 图片优化

```javascript
// utils/imageOptimizer.js
class ImageOptimizer {
  // 图片懒加载
  static lazyLoad() {
    const observer = wx.createIntersectionObserver()

    observer.relativeToViewport({
      bottom: 100 // 提前100px开始加载
    }).observe('.lazy-image', (res) => {
      if (res.intersectionRatio > 0) {
        const img = res.target
        const src = img.dataset.src

        if (src && !img.dataset.loaded) {
          img.dataset.loaded = 'true'

          wx.getImageInfo({
            src: src,
            success: (imageRes) => {
              img.src = imageRes.path
              img.classList.add('loaded')
            },
            fail: () => {
              img.src = '/images/placeholder.png'
              img.classList.add('error')
            }
          })
        }
      }
    })
  }

  // 图片压缩
  static compressImage(src, quality = 0.8) {
    return new Promise((resolve, reject) => {
      wx.compressImage({
        src: src,
        quality: quality * 100,
        success: (res) => {
          resolve(res.tempFilePath)
        },
        fail: (err) => {
          reject(err)
        }
      })
    })
  }

  // 批量处理图片
  static async processImages(imageList) {
    const results = []

    for (const image of imageList) {
      try {
        const compressedImage = await this.compressImage(image.src, image.quality || 0.8)
        results.push({
          ...image,
          compressedSrc: compressedImage
        })
      } catch (error) {
        console.error('图片处理失败:', image.src, error)
        results.push({
          ...image,
          compressedSrc: image.src
        })
      }
    }

    return results
  }
}

module.exports = ImageOptimizer
```

## 4. 小程序与ECharts集成

### 4.1 集成ECharts到小程序

#### 下载和配置

1. 从ECharts官网下载适用于小程序的版本
2. 将 `ec-canvas` 文件夹复制到项目 `components` 目录下

#### 基础配置

```javascript
// components/ec-canvas/ec-canvas.js
import * as echarts from './echarts.min.js'

Component({
  properties: {
    canvasId: {
      type: String,
      value: 'ec-canvas'
    },
    ec: {
      type: Object
    }
  },

  data: {
    isReady: false
  },

  ready() {
    if (!this.data.ec) {
      console.warn('组件需绑定 ec 变量')
      return
    }

    this.init()
  },

  methods: {
    init() {
      const canvasNode = this.selectComponent(`#${this.data.canvasId}`)

      if (!canvasNode) {
        console.warn('Canvas节点不存在')
        return
      }

      const query = this.createSelectorQuery()
      query.select(`#${this.data.canvasId}`)
        .fields({ node: true, size: true })
        .exec((res) => {
          const canvas = res[0].node
          const ctx = canvas.getContext('2d')

          const dpr = wx.getSystemInfoSync().pixelRatio
          canvas.width = res[0].width * dpr
          canvas.height = res[0].height * dpr

          const chart = echarts.init(canvas, null, {
            width: res[0].width,
            height: res[0].height,
            devicePixelRatio: dpr
          })

          canvas.setChart(chart)

          if (this.data.ec && typeof this.data.ec.onInit === 'function') {
            this.data.ec.onInit(canvas, res[0].width, res[0].height, dpr)
          }

          this.chart = chart
          this.setData({ isReady: true })
        })
    },

    // 更新图表配置
    setOption(option, notMerge = false, lazyUpdate = false) {
      if (this.chart) {
        this.chart.setOption(option, notMerge, lazyUpdate)
      }
    },

    // 获取图表实例
    getChart() {
      return this.chart
    }
  }
})
```

### 4.2 实际应用案例

#### 步数统计图表

```javascript
// pages/health/health.js
const CloudService = require('../../utils/cloud')

Page({
  data: {
    ec: {
      onInit: null
    },
    weekStepData: [],
    loading: true
  },

  onLoad() {
    this.initChart()
    this.loadStepData()
  },

  // 初始化图表
  initChart() {
    this.setData({
      ec: {
        onInit: (canvas, width, height, dpr) => {
          this.chart = echarts.init(canvas, null, {
            width: width,
            height: height,
            devicePixelRatio: dpr
          })

          // 设置初始配置
          const option = {
            title: {
              text: '最近7天步数统计',
              left: 'center',
              textStyle: {
                fontSize: 16,
                color: '#333'
              }
            },
            tooltip: {
              trigger: 'axis',
              formatter: '{b}: {c}步'
            },
            xAxis: {
              type: 'category',
              data: [],
              axisLabel: {
                fontSize: 12
              }
            },
            yAxis: {
              type: 'value',
              name: '步数',
              axisLabel: {
                fontSize: 12
              }
            },
            series: [{
              data: [],
              type: 'line',
              smooth: true,
              symbol: 'circle',
              symbolSize: 8,
              lineStyle: {
                color: '#07C160',
                width: 3
              },
              itemStyle: {
                color: '#07C160'
              },
              areaStyle: {
                color: {
                  type: 'linear',
                  x: 0,
                  y: 0,
                  x2: 0,
                  y2: 1,
                  colorStops: [{
                    offset: 0,
                    color: 'rgba(7, 193, 96, 0.3)'
                  }, {
                    offset: 1,
                    color: 'rgba(7, 193, 96, 0.1)'
                  }]
                }
              }
            }]
          }

          this.chart.setOption(option)
          canvas.setChart(this.chart)
        }
      }
    })
  },

  // 加载步数数据
  async loadStepData() {
    try {
      const stepData = await CloudService.getWeRunData()

      if (stepData && stepData.length > 0) {
        // 处理数据
        const weekData = this.processWeekData(stepData)

        // 更新图表
        this.updateChart(weekData)

        this.setData({
          weekStepData: weekData,
          loading: false
        })
      }
    } catch (error) {
      console.error('加载步数数据失败:', error)
      this.setData({ loading: false })

      wx.showToast({
        title: '数据加载失败',
        icon: 'none'
      })
    }
  },

  // 处理周数据
  processWeekData(stepData) {
    const weekData = stepData.slice(-7)

    return weekData.map(item => {
      const date = new Date(item.timestamp * 1000)
      const dateStr = `${date.getMonth() + 1}/${date.getDate()}`

      return {
        date: dateStr,
        steps: item.step,
        timestamp: item.timestamp
      }
    })
  },

  // 更新图表
  updateChart(weekData) {
    if (!this.chart) return

    const dates = weekData.map(item => item.date)
    const steps = weekData.map(item => item.steps)

    const option = {
      xAxis: {
        data: dates
      },
      series: [{
        data: steps
      }]
    }

    this.chart.setOption(option)
  },

  // 切换图表类型
  switchChartType(type) {
    if (!this.chart) return

    const option = {
      series: [{
        type: type, // 'line' 或 'bar'
        smooth: type === 'line'
      }]
    }

    this.chart.setOption(option)
  },

  onUnload() {
    // 销毁图表实例
    if (this.chart) {
      this.chart.dispose()
    }
  }
})
