      //upload为下载的文件信息 可以在外层包一个函数 将upload作为参数传递进来
      `${upload.fileName}.` + `${upload.fileExtension}`
    );
    document.body.appendChild(link);
    //下载该文件
    link.click();
    document.body.removeChild(link);
  })
  .catch((err) => {
    console.log(err);
  });
